    if (!raw || !raw.hash) return null
    const sizeMap = { '128k': [raw.filesize, 128], '320k': [raw['320filesize'] || raw.hqfilesize, 320], flac: [raw.sqfilesize, 740], flac24bit: [raw.resfilesize, 1948] }
